window.__rgjRes=null; window.__rgjErr=null;
(async () => { try {
  const h = await (await fetch('https://retroachievements.org/game/1447')).text();
  const d = new DOMParser().parseFromString(h,'text/html');
  const blob = d.querySelector('script[type="application/json"]');
  const j = JSON.parse(blob.textContent);
  const find = (n,dep) => { if(!n||typeof n!=='object'||dep>8) return null;
    if (Array.isArray(n)&&n.length&&n[0]&&typeof n[0]==='object'&&'title' in n[0]&&'points' in n[0]) return n;
    for (const k in n) { const r=find(n[k],dep+1); if(r) return r; } return null; };
  const arr = find(j,0)||[];
  window.__rgjRes = JSON.stringify(arr.map(a=>({id:a.id,title:a.title,desc:a.description,points:a.points,ratio:a.pointsWeighted,type:a.type||'',unlockedAt:a.unlockedAt||null})));
} catch(e){ window.__rgjErr=String(e); } })();
